        }
    }

    if let Some(n) = number {
        body["page_size"] = json!(n);
    }
    if let Some(ref ob) = order_by {
        body["order_by"] = Value::String(ob.clone());
    }
    if let Some(ref od) = order_dir {
        body["order_dir"] = Value::String(od.clone());
