            };
        }
        if edit {
            return utilities::open_path_in_editor(path);
        }
        if show_path {
            println!("{display_path}");
            return Ok(());
        }
        match super::parser::get_config_from_file(path) {
            Ok(config) => {
                println!("{config}");
                Ok(())
            }
