use crate::api::client::ApiClient;
use crate::constants;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

pub struct BillCommand;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;

fn rounded_duration(duration: i64) -> i64 {
    if duration <= 0 {
        0
    } else {
        ((duration - 1) / BILLING_UNIT_SECONDS + 1) * BILLING_UNIT_SECONDS
    }
}

fn aggregate(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();

    for entry in entries
        .iter()
        .filter(|entry| entry.billable && entry.stop.is_some())
    {
        let project = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| constants::NO_PROJECT.to_string());
        *totals.entry(project).or_default() += rounded_duration(entry.duration);
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

fn print_totals(totals: &[(String, i64)]) {
    if totals.is_empty() {
        println!("(no data)");
        return;
    }

    let total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
    for (project, seconds) in totals {
        println!("{seconds}s  {project}");
    }
    println!("{total}s  Total");
}

impl BillCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        print_totals(&aggregate(&entries));
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::Project;
    use chrono::{TimeZone, Utc};

    fn entry(
        id: i64,
        duration: i64,
        billable: bool,
        stop: bool,
        project: Option<&str>,
    ) -> TimeEntry {
        TimeEntry {
            id,
            description: String::new(),
            start: Utc.timestamp_opt(0, 0).single().unwrap(),
            stop: stop.then(|| Utc.timestamp_opt(1, 0).single().unwrap()),
            duration,
            billable,
            workspace_id: 1,
            tags: vec![],
            project: project.map(|name| Project {
                id,
                name: name.to_string(),
                workspace_id: 1,
                client: None,
                is_private: false,
                active: true,
                at: Utc.timestamp_opt(0, 0).single().unwrap(),
                created_at: Utc.timestamp_opt(0, 0).single().unwrap(),
                color: String::new(),
                billable: None,
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn aggregates_billable_stopped_entries_with_per_entry_rounding_and_ordering() {
        let entries = vec![
            entry(1, 7 * 60, true, true, Some("Zulu")),
            entry(2, 22 * 60, true, true, Some("Alpha")),
            entry(3, 15 * 60, true, true, Some("Alpha")),
            entry(4, 8 * 60, true, true, None),
            entry(5, 60 * 60, false, true, Some("Ignored")),
            entry(6, 60 * 60, true, false, Some("Running")),
        ];

        assert_eq!(
            aggregate(&entries),
            vec![
                ("Alpha".to_string(), 45 * 60),
                ("No Project".to_string(), 15 * 60),
                ("Zulu".to_string(), 15 * 60),
            ]
        );
    }

    #[test]
    fn empty_qualifying_entries_have_no_totals() {
        assert!(aggregate(&[entry(1, 10, false, true, None)]).is_empty());
    }
